const raw = $input.first().json;
let data = raw.output !== undefined ? raw.output : raw;

if (typeof data === 'string') {
  let cleaned = data.trim()
    .replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
  try {
    data = JSON.parse(cleaned);
  } catch (e) {
    return {
      ready: "false",
      message: "عذراً، لم أتمكن من فهم طلبك. هل يمكنك إعادة المحاولة؟"
    };
  }
}

if (data.ready === false || data.ready === "false") {
  return {
    ready: "false",
    message: data.message || "أحتاج معلومات إضافية."
  };
}

const city = data.city || '';
if (!city || city.toLowerCase() === 'unknown') {
  return {
    ready: "false",
    message: "أي مدينة تحديداً تريد زيارتها؟"
  };
}

return {
  ready: "true",
  city: data.city,
  city_ar: data.city_ar || data.city,
  days: data.days || 3,
  travelers: data.travelers || 1,
  budget: data.budget || 'mid-range',
  interests: data.interests || ['sightseeing'],
  email: data.email || ''
};

// دمج بيانات الرحلة الأصلية مع نتيجة الجيوكودينج (lat/lon) في عنصر واحد
const trip = $('Parse Trip Data').first().json;
const geo = $input.first().json;

return {
  ...trip,
  lat: geo.lat,
  lon: geo.lon
};

// تجميع كل البيانات (الرحلة + الطقس + المعالم + الأسعار) في object واحد منظم
// يُمرر للـ AI Agent كنص JSON واضح ضمن الرسالة
const trip = $('Combine Trip + Geo').first().json;
const weather = $('HTTP - Weather API').first().json;
const places = $('HTTP - Places API').first().json;
const prices = $('HTTP - Prices API').first().json;

return {
  trip,
  weather,
  places,
  prices
};

// تنظيف الناتج من أي ```html``` متبقية احتياطاً، ثم تمريره مع باقي البيانات (مثل البريد) للخطوات التالية
const raw = $input.first().json;
let html = raw.output !== undefined ? raw.output : raw;
if (typeof html !== 'string') html = JSON.stringify(html);

html = html.trim()
  .replace(/^```html/i, '')
  .replace(/^```/, '')
  .replace(/```$/, '')
  .trim();

const trip = $('Combine Trip + Geo').first().json;

return {
  html,
  email: trip.email || '',
  city_ar: trip.city_ar || trip.city || ''
};
